import {createHash,randomUUID} from 'node:crypto';
import type {CurrentSession} from '../../../lib/server/auth/sessions';
import type {GapSource} from '../../../lib/contracts/product-gaps';
import {withTransaction} from '../../../lib/server/db/client';
import {withGapDatabase} from './environment';
import {createKnowledgeCandidate,submitKnowledgeCandidate,decideKnowledgeCandidate} from '../../../lib/server/knowledge/service';
import {acceptedGapEvidence} from './evidence';
import {createArtifactDatabaseFixture} from '../artifact-database';
import {claimArtifactRun,publishArtifactRun} from '../../../lib/server/artifacts/jobs';
import {submitArtifactProposal} from '../../../lib/server/artifacts/proposals';
import {submitProfileCommand} from '../../../lib/server/profiles/service';
import {materializeCurrentProjection} from '../../../lib/server/retrieval/projections';
const sha=(s:string)=>createHash('sha256').update(s).digest('hex');
export async function sharedGapEvidence(author:CurrentSession,reviewer:CurrentSession,customerId:string){const accepted=await acceptedGapEvidence(author,reviewer,customerId,'corroboration','Synthetic reusable source for explicit sanitization.');return withTransaction(async db=>{const source=(await db.query('SELECT revision_number,content_digest FROM profile_revisions WHERE id=$1',[accepted.revisionId])).rows[0],payload={title:'Synthetic reusable practice',productVersion:'Unknown',problem:'A reusable observed engineering concern',prerequisites:'Check current applicability',solution:'Measure before choosing a capability',reasoning:'Use observed evidence',applicability:'Independently reviewed contexts',limitations:'Does not establish named account intent',validation:'Verify each original source'},draft=await createKnowledgeCandidate(db,author,{idempotencyKey:randomUUID(),customerId,payload,lineage:[{sourceKind:'accepted_profile',sourceRevisionId:accepted.revisionId,sourceGeneration:Number(source.revision_number),sourceDigest:source.content_digest,rightsBasis:'Explicit synthetic reuse rights'}]});await submitKnowledgeCandidate(db,author,draft.id,{idempotencyKey:randomUUID(),expectedRevision:draft.revision,expectedDigest:draft.digest});const decision=await decideKnowledgeCandidate(db,reviewer,draft.id,{idempotencyKey:randomUUID(),expectedRevision:draft.revision,expectedDigest:draft.digest,action:'publish',rightsAttested:true,sanitizationRationale:'Reviewed every synthetic public field and removed identifying context',checklist:{namesAndDomainsRemoved:true,repositoriesAndLinksRemoved:true,peopleAndCommercialDetailsRemoved:true,identifyingConfigurationAndOutcomesRemoved:true,countsAndCombinedInferenceReviewed:true}});const row=(await db.query("SELECT s.source_generation,s.content_digest,p.locators FROM retrieval_sources s JOIN retrieval_passages p ON p.source_id=s.id WHERE s.source_revision_id=$1 AND s.source_kind='published_shared' AND s.lifecycle_state='current' ORDER BY p.ordinal LIMIT 1",[decision.revisionId])).rows[0];if(!row)throw Error('Synthetic publication projection required');return {revisionId:decision.revisionId,reference:{id:randomUUID(),kind:'shared_knowledge',customerId:null,sourceRevisionId:decision.revisionId,generation:Number(row.source_generation),contentDigest:row.content_digest,locator:row.locators[0],purpose:'corroboration'} as GapSource};});}
export async function excerptGapEvidence(author:CurrentSession,reviewer:CurrentSession,customerId:string){const artifact=await withGapDatabase(async db=>{await db.query('BEGIN');try{const fixture=await createArtifactDatabaseFixture(db,author,customerId),claim=await claimArtifactRun(db);if(!claim||claim.runId!==fixture.runId)throw Error('Exact synthetic extraction claim required');const scan={contract:'artifact-intake-v1' as const,originalDigest:fixture.originalDigest,engineVersion:'1.5.4',signatureVersion:'28137',scanPolicyVersion:'004-v1',scannedAt:new Date().toISOString(),result:'clean' as const},manifest={contract:'artifact-intake-v1',originalDigest:fixture.originalDigest,parserVersion:'004-v1',imageDigest:fixture.imageDigest,scanReceiptDigest:sha(JSON.stringify(scan)),format:'txt',status:'ready',coverage:{total:1,visited:1,omitted:[]},units:[{id:randomUUID(),ordinal:1,text:'Synthetic artifact',locator:{kind:'txt',lineStart:1,lineEnd:1},origin:'native',ocrConfidence:null}],warnings:[]};await publishArtifactRun(claim,manifest,scan,db);const unit=(await db.query('SELECT id FROM artifact_extraction_units WHERE run_id=$1',[fixture.runId])).rows[0];await db.query('COMMIT');return {...fixture,unitId:unit.id};}catch(error){await db.query('ROLLBACK');throw error;}});const proposed=await submitArtifactProposal(author,{selection:{versionId:artifact.versionId,runId:artifact.runId,lifecycleGeneration:1,ranges:[{unitId:artifact.unitId,start:0,end:18}],excerpt:'Synthetic artifact',excerptDigest:sha('Synthetic artifact'),audience:'internal',dataCategory:'other_internal'},command:{action:'propose_record',requestKey:randomUUID(),requestedAudience:'internal',dataCategory:'other_internal',payload:{kind:'claim',text:'Synthetic artifact',sourceType:'manual'},qualityInput:{rubricVersion:'evidence-quality-v1',R:3,D:4,C:1,reliabilityRationale:'Synthetic primary retained text',directnessRationale:'Exact original excerpt',corroborationRationale:'One synthetic original',informationType:'adoption_process',dateBasis:'unknown'}}});return withTransaction(async db=>{const source=(await db.query('SELECT v.content_digest,r.version,r.current_accepted_revision_id FROM profile_revisions v JOIN profile_records r ON r.id=v.record_id WHERE v.id=$1',[proposed.revisionId])).rows[0];await submitProfileCommand(reviewer,customerId,{action:'accept_revision',requestKey:randomUUID(),revisionId:proposed.revisionId,digest:source.content_digest,expectedRecordVersion:Number(source.version),expectedAcceptedRevisionId:source.current_accepted_revision_id,rationale:'Exact synthetic excerpt human review'},db);await materializeCurrentProjection(db,'approved_excerpt',proposed.selectionId,'internal');const row=(await db.query("SELECT s.source_generation,s.content_digest,p.locators FROM retrieval_sources s JOIN retrieval_passages p ON p.source_id=s.id WHERE s.source_kind='approved_excerpt' AND s.source_revision_id=$1 AND s.lifecycle_state='current' ORDER BY p.ordinal LIMIT 1",[proposed.selectionId])).rows[0];if(!row)throw Error('Reviewed synthetic excerpt projection required');return {versionId:artifact.versionId,revisionId:proposed.selectionId,reference:{id:randomUUID(),kind:'approved_excerpt',customerId,sourceRevisionId:proposed.selectionId,generation:Number(row.source_generation),contentDigest:row.content_digest,locator:row.locators[0],purpose:'corroboration'} as GapSource};});}
